  const won = await dbUpdateIfNull('splits', id, {departed_elapsed_seconds: secs, departed_logged_by: ME.name, departed_logged_at: new Date().toISOString()}, 'departed_logged_at');
  await renderSplits();
  if(won) toastUndo('Departure logged', () => undoLastLogAndRefresh(id));
