async function clearActual(id){
  // Full reset of everything logged AT a station on race day — arrival/departure times, the
  // "ran through" flag, the race-day note (and its flag-forward), and any question answers —
  // so it goes back to a clean "not reached yet" state. Works whether the station was checked
  // in, marked ran-through, or just has a stray note. The manager's plan note / official note /
  // bring list stay (those were set in advance, not logged at the stop).
  const rows = await dbList('splits');
  const row = rows.find(r=>r.id===id);
  const hasExtras = row && ((row.station_note && row.station_note.trim()) || row.flag_forward || (row.question_answers && Object.keys(row.question_answers).length));
  if(hasExtras && !confirm('Clear this station? This also erases the race-day note and any question answers logged here.')) return;
  await dbUpdate('splits', id, {
    actual_elapsed_seconds: null, actual_logged_by: null, actual_logged_at: null,
    departed_elapsed_seconds: null, departed_logged_by: null, departed_logged_at: null,
    skipped: false, station_note: '', station_note_by: null, flag_forward: false, question_answers: {}
  });
  await renderSplits();
}
async function toggleSkip(id, skipped){
  const patch = {skipped};
  // A skipped/ran-through stop can't also be the pace anchor, so clear any logged times.
  if(skipped){ patch.actual_elapsed_seconds = null; patch.actual_logged_by = null; patch.actual_logged_at = null; patch.departed_elapsed_seconds = null; patch.departed_logged_by = null; patch.departed_logged_at = null; }
  await dbUpdate('splits', id, patch);
  await renderSplits();
  if(skipped) toastUndo('Marked ran-through', () => undoLastLogAndRefresh(id));
}
