async function editSplit(id, field, value){
  await dbUpdate('splits', id, {[field]: value});
  await renderSplits();
  toast('Saved');
}
// Bad input used to silently become mile 0 (parseFloat(...)||0), which could quietly yank a
// station to the front of the race. Reject it instead, and warn before moving a station that's
// an official cutoff, since its mile is now what the "Room Before Cutoff" math anchors to.
async function editSplitMile(id, value){
  const parsed = parseFloat(value);
  if(value.trim()==='' || isNaN(parsed) || parsed<0){
    toast('Enter a valid mile number', true);
    await renderSplits();
    return;
  }
  const rows = await dbList('splits');
  const row = rows.find(r=>r.id===id);
  if(row && row.is_checkpoint && !confirm(`"${row.station}" is an official race cutoff. Moving its mile also moves where that cutoff applies on course. Continue?`)){
    await renderSplits();
    return;
  }
  await editSplit(id, 'mile', parsed);
}
async function toggleCheckpoint(id, checked){
  await dbUpdate('splits', id, {is_checkpoint: checked});
  await renderSplits();
  toast(checked ? 'Marked as an official cutoff — set its cutoff hours below' : 'Cutoff removed from this stop');
}
async function editCheckpointHours(id, value){
  const parsed = parseFloat(value);
  if(value.trim()==='' || isNaN(parsed) || parsed<=0){
    toast('Enter cutoff hours as a number, e.g. 10.2', true);
    await renderSplits();
    return;
  }
  await editSplit(id, 'checkpoint_cutoff_hours', parsed);
}
async function toggleSplitAssignee(splitId, personId){
  const rows = await dbList('splits', null, {fresh:true});
  const row = rows.find(r=>r.id===splitId);
  if(!row) return;
  const cur = new Set(row.assigned_to || []);
  if(cur.has(personId)) cur.delete(personId); else cur.add(personId);
  await dbUpdate('splits', splitId, {assigned_to:[...cur]});
  await renderSplits();
}
function isManager(){ return !!ME && ME.role === 'Manager'; }
function canEditBring(){ return isManager(); }
async function toggleBringItem(splitId, itemId, checked){
  const rows = await dbList('splits', null, {fresh:true});
  const row = rows.find(r=>r.id===splitId);
  if(!row) return;
  const items = (row.bring_items||[]).map(it=> it.id===itemId ? {...it, checked, checked_by: checked?ME.name:null} : it);
  await dbUpdate('splits', splitId, {bring_items: items});
  await renderSplits();
}
async function toggleBringItemAndRefresh(splitId, itemId, checked){
  await toggleBringItem(splitId, itemId, checked);
  await refreshAfterStopAction(splitId);
}
async function addBringItem(splitId, inputEl){
  if(!canEditBring()) return;
  const label = inputEl.value.trim();
  if(!label) return;
  const rows = await dbList('splits', null, {fresh:true});
  const row = rows.find(r=>r.id===splitId);
  if(!row) return;
  const items = [...(row.bring_items||[]), {id:crypto.randomUUID(), label, checked:false, checked_by:null}];
  await dbUpdate('splits', splitId, {bring_items: items});
  await renderSplits();
}
async function deleteBringItem(splitId, itemId){
  if(!canEditBring()) return;
  const rows = await dbList('splits', null, {fresh:true});
  const row = rows.find(r=>r.id===splitId);
  if(!row) return;
  const item = (row.bring_items||[]).find(it=>it.id===itemId);
  if(!confirm(`Remove "${item ? item.label : 'this item'}" from what to bring?`)) return;
  const items = (row.bring_items||[]).filter(it=>it.id!==itemId);
  await dbUpdate('splits', splitId, {bring_items: items});
  await renderSplits();
}
async function addSplitRow(){
  const rows = await dbList('splits', 'sort_order.asc');
  // Start a new station just past the current last mile, not at 0 — the pace engine keys its
  // goal-time map by mile, so a second row at mile 0 (or any existing mile) collides with the
  // Start row and briefly shows a nonsense goal time until the manager types the real mile.
  const maxMile = rows.reduce((m,r)=> (typeof r.mile==='number' && r.mile>m) ? r.mile : m, 0);
  const newMile = Math.round((maxMile + 0.1) * 10) / 10;
  await dbInsert('splits', {sort_order: rows.length, mile:newMile, station:'New Stop', elapsed_seconds:0, sub:'', note:'', is_custom:true, actual_elapsed_seconds:null, skipped:false, station_note:'', assigned_to:[], address:'', bring_items:[], official_note:'', is_checkpoint:false, checkpoint_cutoff_hours:null, question_answers:{}, elevation_gain_ft:0, elevation_loss_ft:0, is_big_stop:false});
  await renderSplits();
}
async function deleteSplitRow(id){
  const rows = await dbList('splits');
  const row = rows.find(r=>r.id===id);
  if(!confirm(`Delete the "${row ? row.station : 'this'}" stop entirely? This can't be undone.`)) return;
  await dbDelete('splits', id);
  await renderSplits();
}

/* ================= WEEKEND ================= */
/* ---- weekend event data model ----
   No schema change needed: the structured fields (start/end minutes, visibility, creator,
   attendees) live as a JSON blob in the old `time_text` column. Legacy rows hold a plain
   time string ("4:00 PM", "7pm") and are auto-upgraded to JSON on first read. */
const WK_DAYS = ['Thu','Fri','Sat','Sun','Mon'];
const WK_DAY_FULL = {Thu:'Thursday',Fri:'Friday',Sat:'Saturday',Sun:'Sunday',Mon:'Monday'};
const WK_CAL_HOUR_PX = 44;
let WEEKEND_VIEW = (()=>{ try{ return localStorage.getItem('hermesco_weekend_view') || 'list'; }catch(e){ return 'list'; } })();
let editingEventId = null, _emVis = 'public', _wkCalScrolled = false, _emMode = 'edit';
let _wkEventsCache = [];

function parseTimeText(t){
  const s = String(t == null ? '' : t).trim().toLowerCase();
  const m = s.match(/^(\d{1,2})(?::(\d{2}))?\s*(a|p)\.?m\.?$/);
  if(!m) return null;
  let h = parseInt(m[1], 10) % 12;
  if(m[3] === 'p') h += 12;
  return h * 60 + (m[2] ? parseInt(m[2], 10) : 0);
}
function fmtMin(min){
  min = ((Math.round(min) % 1440) + 1440) % 1440;
  let h = Math.floor(min / 60); const m = min % 60;
  const ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${h}:${String(m).padStart(2, '0')} ${ap}`;
}
function fmtMinRange(s, e){
  const sf = fmtMin(s), ef = fmtMin(e);
  return sf.slice(-2) === ef.slice(-2) ? `${sf.slice(0, -3)} – ${ef}` : `${sf} – ${ef}`;
}
function fmtDuration(s, e){
  let d = e - s; if(d <= 0) d += 1440;
  const h = Math.floor(d/60), mm = d%60;
  return (h ? `${h}h` : '') + (h && mm ? ' ' : '') + (mm ? `${mm}m` : '') || '0m';
}
function timeInputToMin(v){ const m = String(v||'').match(/^(\d{1,2}):(\d{2})$/); return m ? parseInt(m[1],10)*60 + parseInt(m[2],10) : null; }
function minToTimeInput(min){ min = ((Math.round(min)%1440)+1440)%1440; return `${String(Math.floor(min/60)).padStart(2,'0')}:${String(min%60).padStart(2,'0')}`; }

// {s, e, v, by, att, addr} for an event — from its JSON time_text, or derived for a legacy row.
function evMeta(ev){
  let m = null;
  try{ const p = JSON.parse(ev.time_text); if(p && typeof p === 'object' && !Array.isArray(p)) m = p; }catch(e){}
  if(m){
    const s = Number.isFinite(m.s) ? m.s : 720;
    return { s, e: Number.isFinite(m.e) ? m.e : s + 60, v: m.v === 'private' ? 'private' : 'public',
             by: m.by || null, att: Array.isArray(m.att) ? m.att : [], addr: m.addr || '' };
  }
  const s = parseTimeText(ev.time_text);
  return { s: s == null ? 720 : s, e: (s == null ? 720 : s) + 60, v: 'public', by: null, att: [], addr: '' };
}
function evMetaJson(meta){ return JSON.stringify({ s: meta.s, e: meta.e, v: meta.v, by: meta.by, att: meta.att, addr: meta.addr || '' }); }
function evColor(ev){
  const by = evMeta(ev).by;
  const p = by ? PROFILES.find(x => x.id === by) : null;
  return (p && p.color) || '#7A7268';
}
function evCreatorName(ev){
  const by = evMeta(ev).by;
  const p = by ? PROFILES.find(x => x.id === by) : null;
  return p ? p.name : null;
}
function canEditEvent(ev){ return !!(isManager() || (evMeta(ev).by && evMeta(ev).by === ME.id)); }
function visibleEvents(events){ return events.filter(ev => { const m = evMeta(ev); return m.v !== 'private' || m.by === ME.id; }); }
// Populate the modal's day picker with real dates ("Thu · 10/8").
function populateEmDayOptions(){
  const sel = document.getElementById('em-day');
  if(sel.options.length) return;
  sel.innerHTML = WK_DAYS.map(d=>{ const dd = wkDateFor(d); return `<option value="${d}">${d} · ${dd.getMonth()+1}/${dd.getDate()}</option>`; }).join('');
}
// The real calendar date for a weekend day label (race is Fri; Thu is the day before, etc.).
function wkDateFor(day){
  const base = raceStartDateTime();
  const off = { Thu: -1, Fri: 0, Sat: 1, Sun: 2, Mon: 3 }[day] ?? 0;
  const d = new Date(base.getFullYear(), base.getMonth(), base.getDate() + off);
  return d;
}

async function renderWeekend(){
  document.getElementById('lg-name').value = CONFIG.lodging_name || '';
  document.getElementById('lg-address').value = CONFIG.lodging_address || '';
  document.getElementById('lg-checkin').value = CONFIG.lodging_checkin || '';
  document.getElementById('lg-checkout').value = CONFIG.lodging_checkout || '';
  document.getElementById('lg-notes').value = CONFIG.lodging_notes || '';
  ['lg-name','lg-address','lg-checkin','lg-checkout','lg-notes'].forEach(id=>{
    document.getElementById(id).onblur = async (e) => {
      const key = {'lg-name':'lodging_name','lg-address':'lodging_address','lg-checkin':'lodging_checkin','lg-checkout':'lodging_checkout','lg-notes':'lodging_notes'}[id];
      await dbSetConfig(key, e.target.value);
      CONFIG[key] = e.target.value;
      toast('Saved');
    };
  });

  let events = await dbList('timeline_events', 'sort_order.asc');
  // one-time upgrade: rewrite any legacy free-text time into the JSON blob
  const legacy = events.filter(ev => { try{ const p = JSON.parse(ev.time_text); return !(p && typeof p === 'object'); }catch(e){ return true; } });
  if(legacy.length){
    for(const ev of legacy){ await dbUpdate('timeline_events', ev.id, { time_text: evMetaJson(evMeta(ev)) }); }
    events = await dbList('timeline_events', 'sort_order.asc');
  }
  _wkEventsCache = events;

  const shown = visibleEvents(events);
  document.getElementById('weekend-list-wrap').classList.toggle('hidden', WEEKEND_VIEW !== 'list');
  document.getElementById('weekend-cal-wrap').classList.toggle('hidden', WEEKEND_VIEW !== 'calendar');
  document.getElementById('weekend-cal-hint').classList.toggle('hidden', WEEKEND_VIEW !== 'calendar');
  document.getElementById('wk-toggle-list').classList.toggle('active', WEEKEND_VIEW === 'list');
  document.getElementById('wk-toggle-cal').classList.toggle('active', WEEKEND_VIEW === 'calendar');
  if(WEEKEND_VIEW === 'list') renderWeekendList(shown);
  else renderWeekendCalendar(shown);
}
function setWeekendView(v){
  WEEKEND_VIEW = v;
  _wkCalScrolled = false;                 // re-center the grid when you switch into it
  try{ localStorage.setItem('hermesco_weekend_view', v); }catch(e){}
  renderWeekend();
}
// Compact attendee row for the list: colored pills for who's actually going, a one-tap
// "I'm going" for yourself, and (managers only) an "assign…" that opens the full picker.
function attendeePillsHTML(ev){
  const att = evMeta(ev).att;
  const going = PROFILES.filter(p => att.includes(p.id));
  const iAmGoing = att.includes(ME.id);
  let pills = going.map(p=>{
    const canRemove = isManager() || p.id === ME.id;
    const style = `background:${p.color || 'var(--grad)'};color:${p.color ? contrastText(p.color) : '#fff'}`;
    return `<button type="button" class="ev-pill on" style="${style}" ${canRemove ? `onclick="toggleEventAttendee('${ev.id}','${p.id}')"` : 'disabled'}>${esc(p.name)}${canRemove ? ' ✕' : ''}</button>`;
  }).join('');
  if(!iAmGoing) pills += `<button type="button" class="ev-pill ev-pill-add" onclick="toggleEventAttendee('${ev.id}','${ME.id}')"><i class="ti ti-plus" style="font-size:11px"></i> I'm going</button>`;
  if(isManager()) pills += `<button type="button" class="ev-pill ev-pill-add" onclick="openEventModal('${ev.id}')">assign…</button>`;
  const label = going.length ? `Going · ${going.length}` : 'Nobody signed up yet';
  return `<div class="ev-going-lbl ${going.length ? '' : 'empty'}">${label}</div><div class="ev-pills">${pills}</div>`;
}
function renderWeekendList(events){
  const byDay = {}; WK_DAYS.forEach(d => byDay[d] = []);
  events.forEach(ev => { (byDay[ev.day_label] || byDay.Sat).push(ev); });
  let html = '';
  const now = new Date();
  const todayLabel = WK_DAYS.find(d=>{ const dd = wkDateFor(d); return now.getFullYear()===dd.getFullYear() && now.getMonth()===dd.getMonth() && now.getDate()===dd.getDate(); });
  WK_DAYS.forEach(d=>{
    // earliest start first; if two start together, the one that ends first comes first
    const list = (byDay[d] || []).sort((a,b) => { const ma = evMeta(a), mb = evMeta(b); return (ma.s - mb.s) || (ma.e - mb.e); });
    if(d === 'Mon' && !list.length) return;
    const dim = d === 'Mon';
    const dd = wkDateFor(d);
    html += `<div class="wk-day-head ${dim ? 'dim' : ''} ${todayLabel===d ? 'today' : ''}">${WK_DAY_FULL[d]} <span class="wk-dh-date">${dd.getMonth()+1}/${dd.getDate()}</span>${todayLabel===d ? ' <span class="wk-dh-today">TODAY</span>' : ''}${dim ? ' <span>· if anyone’s still around</span>' : ''}</div>`;
    if(!list.length){ html += `<div class="profile-empty" style="padding:6px 0 2px">Nothing scheduled.</div>`; return; }
    html += list.map(ev=>{
      const m = evMeta(ev), creator = evCreatorName(ev), overnight = m.e <= m.s;
      return `<div class="wk-list-ev ${dim ? 'dim' : ''}" style="border-left-color:${evColor(ev)}">
        <div class="wk-le-top">
          <div class="wk-le-title">${esc(ev.title)}</div>
          ${canEditEvent(ev) ? `<button class="tl-del" title="Edit" onclick="openEventModal('${ev.id}')"><i class="ti ti-pencil"></i></button>` : ''}
        </div>
        <div class="wk-le-time"><i class="ti ti-clock" style="font-size:12px"></i> ${fmtMin(m.s)} &nbsp;&ndash;&nbsp; ${fmtMin(m.e)}${overnight ? ' <span style="opacity:.7">(next morning)</span>' : ''}${creator ? ` &nbsp;·&nbsp; ${esc(creator)}` : ''}${m.v === 'private' ? ' &nbsp;·&nbsp; <i class="ti ti-lock" style="font-size:11px"></i> private' : ''}</div>
        ${m.addr ? `<div style="margin-top:6px">${addressBlock(m.addr)}</div>` : ''}
        ${ev.notes ? `<div class="tl-notes">${esc(ev.notes)}</div>` : ''}
        ${attendeePillsHTML(ev)}
      </div>`;
    }).join('');
  });
  document.getElementById('weekend-list-wrap').innerHTML = html || '<div class="profile-empty">No events yet — tap "Add an event".</div>';
}
// Google-Calendar-style column layout: split events into clusters that actually overlap, so a
// lone 6am event stays full-width even if there's a 3-way pile-up at 2pm.
function layoutColumn(items){
  items.sort((a,b)=> a.s - b.s || a.eEff - b.eEff);
  let cluster = [], clusterEnd = -1;
  const flush = () => {
    if(!cluster.length) return;
    const laneEnd = [];
    cluster.forEach(it=>{
      let lane = laneEnd.findIndex(end => end <= it.s);
      if(lane < 0){ lane = laneEnd.length; laneEnd.push(it.eEff); } else laneEnd[lane] = it.eEff;
      it.lane = lane;
    });
    cluster.forEach(it=> it.lanes = laneEnd.length);
    cluster = []; clusterEnd = -1;
  };
  items.forEach(it=>{
    if(cluster.length && it.s >= clusterEnd) flush();
    cluster.push(it);
    clusterEnd = Math.max(clusterEnd, it.eEff);
  });
  flush();
  return items;
}
function renderWeekendCalendar(events){
  const wrap = document.getElementById('weekend-cal-wrap');
  const prevScroll = wrap.scrollTop;
  const H = WK_CAL_HOUR_PX, totalH = 24 * H;
  const avail = (wrap.clientWidth || 320) - 42;
  const dayW = Math.max(66, Math.floor((avail - 3) / 4));
  const monW = Math.round(dayW * 0.62);

  // bucket by day; an overnight event (end <= start) also drops a continuation into the next day
  const byDay = {}; WK_DAYS.forEach(d => byDay[d] = []);
  events.forEach(ev=>{
    const m = evMeta(ev);
    const overnight = m.e <= m.s;
    byDay[ev.day_label]?.push({ ev, s: m.s, e: m.e, addr: m.addr, overnight, cont: false, eEff: overnight ? 1440 : m.e });
    if(overnight){
      const ni = WK_DAYS.indexOf(ev.day_label) + 1;
      if(ni < WK_DAYS.length) byDay[WK_DAYS[ni]].push({ ev, s: 0, e: m.e, addr: m.addr, overnight, cont: true, eEff: m.e });
    }
  });

  const now = new Date();
  let nowDay = null, nowTop = 0;
  WK_DAYS.forEach(d=>{ const dd = wkDateFor(d);
    if(now.getFullYear()===dd.getFullYear() && now.getMonth()===dd.getMonth() && now.getDate()===dd.getDate()){
      nowDay = d; nowTop = (now.getHours()*60 + now.getMinutes())/60 * H;
    }});
  // where to land the vertical scroll on first open: the now-line, else the earliest event
  // (clamped to a 5am–9am band so one lone overnight event can't pin the view to midnight)
  let earliest = null;
  WK_DAYS.forEach(d => (byDay[d]||[]).forEach(it => { if(!it.cont && (earliest == null || it.s < earliest)) earliest = it.s; }));
  const scrollStartMin = earliest == null ? 480 : Math.min(Math.max(earliest, 300), 540);

  const gutter = `<div class="wk-cal-gutter"><div class="wk-cal-corner"></div>${
    Array.from({length:24},(_,h)=>`<div class="wk-hour" style="height:${H}px">${h===0?'':(h%12||12)+(h<12?'a':'p')}</div>`).join('')}</div>`;

  const cols = WK_DAYS.map(d=>{
    const items = layoutColumn(byDay[d] || []);
    const blocks = items.map(it=>{
      const c = evColor(it.ev), txt = c[0]==='#' ? contrastText(c) : '#fff';
      const visEnd = Math.min(it.eEff, 1440);
      const top = it.s/60*H, height = Math.max(17, (visEnd - it.s)/60*H - 2);
      const bw = 100/it.lanes, left = it.lane*bw;
      const cls = 'wk-cal-ev' + (it.cont ? ' cont' : '') + (it.overnight && !it.cont ? ' runover' : '');
      return `<div class="${cls}" style="top:${top}px;height:${height}px;left:calc(${left}% + 1px);width:calc(${bw}% - 3px);background:${c};color:${txt}" onclick="event.stopPropagation();openEventModal('${it.ev.id}')">
        <div class="wk-ce-title">${it.cont ? '<i class="ti ti-arrow-up" style="font-size:9px"></i> ' : (it.addr ? '<i class="ti ti-map-pin" style="font-size:9px"></i> ' : '')}${esc(it.ev.title)}</div>${height > 27 && !it.cont ? `<div class="wk-ce-time">${fmtMin(it.s)}${it.overnight ? ' →' : ''}</div>` : ''}</div>`;
    }).join('');
    const gl = Array.from({length:24},(_,h)=>`<div class="wk-grid-line" style="top:${h*H}px"></div>`).join('');
    const nl = nowDay===d ? `<div class="wk-now" style="top:${nowTop}px"></div>` : '';
    const dd = wkDateFor(d), isToday = nowDay===d;
    return `<div class="wk-cal-day ${d==='Mon'?'mon':''}" style="width:${d==='Mon'?monW:dayW}px">
      <div class="wk-cal-dayhead ${d==='Mon'?'dim':''} ${isToday?'today':''}">${d}<span class="wk-cal-date">${dd.getMonth()+1}/${dd.getDate()}</span></div>
      <div class="wk-cal-body" style="height:${totalH}px" data-day="${d}" onclick="wkCalSlotClick(event)">${gl}${blocks}${nl}</div>
    </div>`;
  }).join('');

  wrap.innerHTML = `<div class="wk-cal">${gutter}${cols}</div>`;
  void wrap.offsetHeight;  // force layout so scrollHeight is known before we set scrollTop
  // keep the reader's place on live re-renders; only jump on first open / view switch
  if(_wkCalScrolled){ wrap.scrollTop = prevScroll; }
  else {
    const target = nowDay ? nowTop - 130 : scrollStartMin/60*H - 20;
    wrap.scrollTop = Math.max(0, target);
    _wkCalScrolled = true;
  }
}
// Tap an empty spot on the grid -> new event that day, starting at that time (rounded to 15m).
function wkCalSlotClick(e){
  const body = e.currentTarget;
  const y = e.clientY - body.getBoundingClientRect().top;
  let min = Math.round((y / WK_CAL_HOUR_PX * 60) / 15) * 15;
  min = Math.max(0, Math.min(1425, min));
  openEventModal(null, { day: body.dataset.day, start: min });
}
let _emAtt = new Set();
// The "who's going" pill row. In edit mode it stages changes in _emAtt (saved with the form);
// in view mode (someone else's event) it writes each toggle straight through.
function renderModalAttendees(){
  let att = _emAtt;
  if(_emMode === 'view'){
    const ev = _wkEventsCache.find(e=>e.id===editingEventId);
    att = new Set(ev ? evMeta(ev).att : []);
  }
  document.getElementById('em-attendees').innerHTML = PROFILES.map(p=>{
    const on = att.has(p.id);
    const clickable = isManager() || p.id === ME.id;
    const style = on ? `background:${p.color || 'var(--grad)'};color:${p.color ? contrastText(p.color) : '#fff'}` : '';
    return `<button type="button" class="ev-pill ${on ? 'on' : ''}" style="${style}" ${clickable ? `onclick="toggleModalAttendee('${p.id}')"` : 'disabled'}>${esc(p.name)}${on ? ' ✓' : ''}</button>`;
  }).join('');
}
async function toggleModalAttendee(personId){
  if(!(isManager() || personId === ME.id)) return;
  if(_emMode === 'view'){
    await toggleEventAttendee(editingEventId, personId);   // writes + re-renders the page
    renderModalAttendees();
    return;
  }
  if(_emAtt.has(personId)) _emAtt.delete(personId); else _emAtt.add(personId);
  renderModalAttendees();
}
function setEmMode(mode){
  _emMode = mode;
  const view = mode === 'view';
  document.getElementById('em-form').hidden = view;
  document.getElementById('em-view').hidden = !view;
  document.getElementById('em-actions-edit').hidden = view;
  document.getElementById('em-actions-view').hidden = !view;
}
function fillEventModal(ev, m){
  populateEmDayOptions();
  document.getElementById('em-title').value = ev.title || '';
  document.getElementById('em-day').value = WK_DAYS.includes(ev.day_label) ? ev.day_label : 'Fri';
  document.getElementById('em-start').value = minToTimeInput(m.s);
  document.getElementById('em-end').value = minToTimeInput(m.e);
  document.getElementById('em-addr').value = m.addr || '';
  document.getElementById('em-notes').value = ev.notes || '';
  _emAtt = new Set(m.att);
  setEventVis(m.v);
  updateEndHint();
  // read-only view block
  const dd = wkDateFor(ev.day_label);
  const creator = evCreatorName(ev);
  document.getElementById('em-view').innerHTML = `
    <div class="emv-time"><i class="ti ti-calendar-event"></i> ${WK_DAY_FULL[ev.day_label] || ev.day_label} ${dd.getMonth()+1}/${dd.getDate()} &nbsp;·&nbsp; ${fmtMin(m.s)} – ${fmtMin(m.e)}${m.e<=m.s?' <span style="opacity:.7">(next morning)</span>':''} &nbsp;·&nbsp; ${fmtDuration(m.s,m.e)}</div>
    ${m.addr ? `<div class="emv-addr">${addressBlock(m.addr)}</div>` : ''}
    ${ev.notes ? `<div class="emv-notes">${esc(ev.notes)}</div>` : ''}
    <div class="emv-meta">${creator ? `Added by ${esc(creator)}` : ''}${m.v==='private' ? ' &nbsp;·&nbsp; <i class="ti ti-lock" style="font-size:11px"></i> private' : ''}</div>`;
  renderModalAttendees();
}
function openEventModal(id, prefill){
  editingEventId = id || null;
  populateEmDayOptions();
  ['em-title','em-addr','em-notes'].forEach(x=>document.getElementById(x).value='');
  document.getElementById('em-attendees').innerHTML = '';
  document.getElementById('em-endhint').textContent = '';
  document.getElementById('em-discard').textContent = id ? 'Delete' : 'Discard';
  const modal = document.getElementById('event-modal');
  if(id){
    const cached = _wkEventsCache.find(e=>e.id===id);
    const show = (ev) => {
      if(editingEventId !== id) return;
      if(!ev){ closeEventModal(); return; }
      const editable = canEditEvent(ev);
      setEmMode(editable ? 'edit' : 'view');
      document.getElementById('em-heading').textContent = editable ? 'Edit event' : (ev.title || 'Event');
      fillEventModal(ev, evMeta(ev));
      if(editable) setTimeout(()=>document.getElementById('em-title').focus(), 50);
    };
    if(cached) show(cached);
    else dbList('timeline_events').then(evs => show(evs.find(e=>e.id===id)));
  } else {
    setEmMode('edit');
    document.getElementById('em-heading').textContent = 'Add an event';
    const start = (prefill && Number.isFinite(prefill.start)) ? prefill.start : 18*60;
    document.getElementById('em-day').value = (prefill && WK_DAYS.includes(prefill.day)) ? prefill.day : 'Fri';
    document.getElementById('em-start').value = minToTimeInput(start);
    document.getElementById('em-end').value = minToTimeInput(Math.min(1425, start + 60));
    _emAtt = new Set([ME.id]);
    renderModalAttendees();
    setEventVis('public');
    updateEndHint();
    setTimeout(()=>document.getElementById('em-title').focus(), 50);
  }
  modal.classList.remove('hidden');
}
function updateEndHint(){
  const s = timeInputToMin(document.getElementById('em-start').value);
  const e = timeInputToMin(document.getElementById('em-end').value);
  const hint = document.getElementById('em-endhint');
  if(s == null || e == null){ hint.textContent = ''; return; }
  hint.textContent = e <= s ? `runs overnight — ends next morning · ${fmtDuration(s,e)}` : `${fmtDuration(s,e)} long`;
}
function closeEventModal(){ document.getElementById('event-modal').classList.add('hidden'); editingEventId = null; _emAtt = new Set(); _emMode = 'edit'; }
function setEventVis(v){
  _emVis = v === 'private' ? 'private' : 'public';
  document.getElementById('em-vis-public').classList.toggle('active', _emVis === 'public');
  document.getElementById('em-vis-private').classList.toggle('active', _emVis === 'private');
}
async function saveEvent(){
  const title = document.getElementById('em-title').value.trim();
  if(!title){ toast('Give it a title', true); return; }
  const day = document.getElementById('em-day').value;
  let s = timeInputToMin(document.getElementById('em-start').value);
  let e = timeInputToMin(document.getElementById('em-end').value);
  if(s == null){ toast('Set a start time', true); return; }
  if(e == null) e = Math.min(1425, s + 60);
  // e <= s is allowed and means "runs past midnight into the next day" — only a dead-equal
  // start/end is nudged to a real duration.
  if(e === s) e = (s + 60) % 1440;
  const notes = document.getElementById('em-notes').value.trim();
  const addr = document.getElementById('em-addr').value.trim();
  const att = [..._emAtt];
  if(editingEventId){
    const evs = await dbList('timeline_events', null, {fresh:true});
    const ev = evs.find(x=>x.id===editingEventId);
    if(!ev || !canEditEvent(ev)){ closeEventModal(); return; }
    const meta = { ...evMeta(ev), s, e, v: _emVis, att, addr };
    await dbUpdate('timeline_events', editingEventId, { title, day_label: day, notes, time_text: evMetaJson(meta) });
  } else {
    const evs = await dbList('timeline_events');
    const nextOrder = evs.reduce((mx, r) => Math.max(mx, r.sort_order || 0), 0) + 1;
    const meta = { s, e, v: _emVis, by: ME.id, att, addr };
    await dbInsert('timeline_events', { title, day_label: day, notes, time_text: evMetaJson(meta), sort_order: nextOrder });
  }
  closeEventModal();
  await renderWeekend();
  toast('Saved');
}
// The left modal button: "Discard" for a brand-new event, "Delete" for an existing one.
async function discardEvent(){
  if(editingEventId){
    const evs = await dbList('timeline_events');
    const ev = evs.find(e=>e.id===editingEventId);
    if(ev && !canEditEvent(ev)){ closeEventModal(); return; }
    if(!confirm(`Delete "${ev ? ev.title : 'this event'}"?`)) return;
    await dbDelete('timeline_events', editingEventId);
    closeEventModal();
    await renderWeekend();
    return;
  }
  if(document.getElementById('em-title').value.trim() && !confirm('Discard this event without saving?')) return;
  closeEventModal();
}
async function toggleEventAttendee(id, personId){
  if(!(isManager() || personId === ME.id)) return;
  const evs = await dbList('timeline_events', null, {fresh:true});
  const ev = evs.find(e=>e.id===id);
  if(!ev) return;
  const meta = evMeta(ev);
  const att = new Set(meta.att);
  if(att.has(personId)) att.delete(personId); else att.add(personId);
  await dbUpdate('timeline_events', id, { time_text: evMetaJson({ ...meta, att: [...att] }) });
  await renderWeekend();
}

/* ================= NOTES ================= */
let editingNoteId = null;
function noteAccentColor(authorName){
  const p = PROFILES.find(pr=>pr.name===authorName);
  if(!p || !p.color) return getComputedStyle(document.documentElement).getPropertyValue('--accent2') || '#7851A9';
  return relLuminance(p.color) > 0.85 ? '#E5484D' : p.color;
}
// Roll up everything logged out on the course — the per-stop race-day notes and every
// answered crew question — so they live in one place instead of hiding inside each stop.
async function renderCourseLog(){
  const el = document.getElementById('course-log');
  if(!el) return;
  const splits = await dbList('splits', 'sort_order.asc');
  const qText = {};
  getCrewQuestions().forEach(q => { qText[q.id] = q.text; });
  const entries = [];
  splits.forEach(s => {
    const where = `${esc(s.station)} · mi ${s.mile}`;
    const ans = s.question_answers || {};
    Object.entries(ans).forEach(([qid, a]) => {
      if(!a || a.value == null || a.value === '') return;
      entries.push({ mile: s.mile, sort: s.sort_order, where, label: qText[qid] || a.q || 'Question', value: a.value, by: a.by || '' });
    });
    if(s.station_note && s.station_note.trim()){
      entries.push({ mile: s.mile, sort: s.sort_order, where, label: 'Note', value: s.station_note.trim(), by: s.station_note_by || '' });
    }
  });
  if(!entries.length){
    el.innerHTML = '<div class="profile-empty">Nothing logged from the aid stations yet — race-day notes and answered questions collect here.</div>';
    return;
  }
  entries.sort((a, b) => b.sort - a.sort);
  el.innerHTML = entries.map(e => `
    <div class="clog-item">
      <div class="clog-where">${e.where}</div>
      <div class="clog-q">${esc(e.label)}</div>
      <div class="clog-a">${esc(e.value)}</div>
      ${e.by ? `<div class="clog-by">— ${esc(e.by)}</div>` : ''}
    </div>`).join('');
}
async function renderNotes(){
  document.getElementById('notes-official').href = safeUrl(CONFIG.official_site_url);
  document.getElementById('notes-ultrapacer').href = safeUrl(CONFIG.ultrapacer_url);
  await renderCourseLog();
  const notes = await dbList('notes', 'created_at.asc');
  const list = document.getElementById('notes-list');
  if(!notes.length){ list.innerHTML = '<div class="profile-empty">No notes yet.</div>'; return; }
  list.innerHTML = notes.map((n,i)=>{
    const isLast = i===notes.length-1;
    const accent = noteAccentColor(n.author);
    const dateStr = new Date(n.created_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
    const arrow = i>0 ? '<div class="note-arrow"><i class="ti ti-arrow-down"></i></div>' : '';
    const isEditing = n.id === editingNoteId;
    const body = isEditing
      ? `<textarea class="note-edit-area" id="note-edit-${n.id}">${esc(n.body)}</textarea>
         <div class="modal-actions" style="margin-top:0">
           <button class="btn ghost sm" style="flex:1" onclick="cancelEditNote()">Cancel</button>
           <button class="btn sm" style="flex:1" onclick="saveEditNote('${n.id}', document.getElementById('note-edit-${n.id}').value)">Save</button>
         </div>`
      : `<div class="note-body">${esc(n.body)}</div>
         <div class="note-footer">
           <div class="note-meta" style="color:${accent}">${isLast?'Current Note — ':''}${dateStr} — ${esc(n.author)}</div>
           <div class="note-actions">
             <button onclick="startEditNote('${n.id}')" title="Edit"><i class="ti ti-pencil"></i></button>
             <button onclick="deleteNote('${n.id}')" title="Delete"><i class="ti ti-trash"></i></button>
           </div>
         </div>`;
    return `${arrow}<div class="note ${isLast?'current':''}" style="${isLast?`border-color:${accent}`:''}">${body}</div>`;
  }).join('');
}
async function submitNote(){
  const el = document.getElementById('note-input');
  const body = el.value.trim();
  if(!body) return;
  await dbInsert('notes', {author: ME.name, body});
  el.value = '';
  await renderNotes();
  toast('Note posted');
}
function startEditNote(id){ editingNoteId = id; renderNotes(); }
function cancelEditNote(){ editingNoteId = null; renderNotes(); }
async function saveEditNote(id, value){
  const body = value.trim();
  if(!body) return;
  await dbUpdate('notes', id, {body});
  editingNoteId = null;
  await renderNotes();
  toast('Note updated');
}
async function deleteNote(id){
  if(!confirm("Delete this note? This can't be undone.")) return;
  await dbDelete('notes', id);
  await renderNotes();
  toast('Note deleted');
}

/* ================= TEAM ================= */
// Anyone can pick any profile at the login screen — there's no PIN — but promoting someone
// TO Manager is a separate, narrower gate: only Victoria and Michelle can do it, by design
// (not "any Manager"), so an existing Manager can't casually hand out more Manager access.
const ROLE_OPTIONS = ['Crew','Pacer','Family','Manager','Runner'];
function canManageRoles(){ return !!ME && (ME.name==='Victoria' || ME.name==='Michelle'); }
function roleOptionsHTML(selected, allowManager){
  return ROLE_OPTIONS.filter(r => allowManager || r!=='Manager' || r===selected)
    .map(r=>`<option ${r===selected?'selected':''}>${r}</option>`).join('');
}
async function renderTeam(){
  PROFILES = await dbList('profiles', 'created_at.asc');
  const grid = document.getElementById('team-grid');
  const canEdit = canManageRoles();
  grid.innerHTML = PROFILES.map(p=>`
    <div class="profile-card" style="${canEdit?'cursor:pointer':'cursor:default'};${p.color?`border-color:${displayColor(p.color)}`:''}" ${canEdit?`onclick="openEditPerson('${p.id}')"`:''}>
      <div class="avatar" style="background:${p.color||'var(--grad)'};color:${p.color?contrastText(p.color):'#fff'}">${initials(p.name)}</div>
      <div class="pname">${esc(p.name)}</div>
      <div class="pill">${esc(p.role)}</div>
    </div>`).join('');
  if(ME.role === 'Manager'){
    grid.innerHTML += `<div class="add-person-card" onclick="openAddPerson()"><i class="ti ti-user-plus" style="font-size:26px"></i>Add Person</div>`;
  }
}
function openAddPerson(){
  document.getElementById('np-role').innerHTML = roleOptionsHTML('Crew', canManageRoles());
  document.getElementById('np-role-hint').textContent = canManageRoles() ? '' : 'Only Victoria and Michelle can add someone as a Manager.';
  document.getElementById('add-person-modal').classList.remove('hidden');
}
function closeAddPerson(){ document.getElementById('add-person-modal').classList.add('hidden'); document.getElementById('np-name').value=''; }
async function submitAddPerson(){
  const name = document.getElementById('np-name').value.trim();
  const role = document.getElementById('np-role').value;
  if(!name) return;
  const existing = await dbList('profiles');
  const color = CREW_PALETTE[existing.length % CREW_PALETTE.length];
  await dbInsert('profiles', {name, role, color});
  closeAddPerson();
  await renderTeam(); await renderHome();
  toast(`${name} added to the crew`);
}
let editPersonId = null;
// canManageRoles() is keyed on exact name, on purpose ("me and Michelle" specifically, not
// "whoever holds Manager"). That means renaming Victoria or Michelle through this same screen
// would silently strip their own role-management access with no way to get it back except a
// direct database edit — so their name field is locked here rather than left as a footgun.
const PROTECTED_ADMIN_NAMES = ['Victoria','Michelle'];
function openEditPerson(id){
  if(!canManageRoles()) return;
  const p = PROFILES.find(x=>x.id===id);
  if(!p) return;
  editPersonId = id;
  const isProtected = PROTECTED_ADMIN_NAMES.includes(p.name);
  const nameInput = document.getElementById('ep-name');
  nameInput.value = p.name;
  nameInput.readOnly = isProtected;
  document.getElementById('ep-role').innerHTML = roleOptionsHTML(p.role, true);
  document.getElementById('ep-role-hint').textContent = isProtected ? "Victoria and Michelle's names are locked — they control who can be a Manager, so renaming them here isn't allowed." : '';
  document.getElementById('edit-person-modal').classList.remove('hidden');
}
function closeEditPerson(){ document.getElementById('edit-person-modal').classList.add('hidden'); editPersonId = null; document.getElementById('ep-name').readOnly = false; }
async function submitEditPerson(){
  if(!editPersonId || !canManageRoles()) return;
  const p = PROFILES.find(x=>x.id===editPersonId);
  const isProtected = p && PROTECTED_ADMIN_NAMES.includes(p.name);
  // Belt-and-suspenders: even if the readonly attribute got bypassed client-side, never
  // actually persist a name change for a protected admin.
  const name = isProtected ? p.name : document.getElementById('ep-name').value.trim();
  const role = document.getElementById('ep-role').value;
  if(!name) return;
  await dbUpdate('profiles', editPersonId, {name, role});
  closeEditPerson();
  await renderTeam(); await renderHome();
  toast('Crew member updated');
}
async function removeEditPerson(){
  if(!editPersonId || !canManageRoles()) return;
  const p = PROFILES.find(x=>x.id===editPersonId);
  if(p && PROTECTED_ADMIN_NAMES.includes(p.name)){
    toast(`${p.name} can't be removed — one of you two has to stay to manage roles`, true);
    return;
  }
  if(!confirm(`Remove ${p ? p.name : 'this person'} from the crew? This can't be undone.`)) return;
  await dbDelete('profiles', editPersonId);
  closeEditPerson();
  await renderTeam(); await renderHome();
  toast('Removed from crew');
}

/* ================= LIVE SYNC ================= */
// Every SYNC_MS the app quietly re-checks the shared data — splits, config (questions,
// reminders, rest-time/quit/reasons text, crew-access mile, race info), notes, and the crew
// roster. If anyone else changed anything, the page you're on re-renders — no button, no manual
// refresh. Pauses while the screen is off / tab hidden (catches up instantly on reopen), and
// never yanks the page while you're typing in a field.
const SYNC_MS = 5000;
let _syncTimer = null, _syncSnapshot = null;
function syncSnapshotOf(rows){
  return JSON.stringify((rows||[]).map(r=>[
    r.id, r.mile, r.station, r.actual_elapsed_seconds, r.actual_logged_at, r.actual_logged_by,
    r.departed_elapsed_seconds, r.departed_logged_at, r.departed_logged_by, r.skipped,
    r.station_note||'', r.station_note_by||'', r.flag_forward, r.official_note||'', r.address||'',
    r.is_checkpoint, r.checkpoint_cutoff_hours, r.note||'',
    JSON.stringify(r.question_answers||{}), JSON.stringify(r.bring_items||[]), JSON.stringify(r.assigned_to||[])
  ]));
}
async function liveSyncTick(){
  if(!USE_SUPABASE || document.hidden || !ME) return;
  const ae = document.activeElement;
  if(ae && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName)) return; // don't interrupt mid-edit
  let rows, cfg, notes, profs, tl;
  try{
    [rows, cfg, notes, profs, tl] = await Promise.all([
      dbList('splits', 'sort_order.asc'), dbGetConfig(),
      dbList('notes', 'created_at.asc'), dbList('profiles', 'created_at.asc'),
      dbList('timeline_events', 'sort_order.asc'),
    ]);
  }catch(e){ return; }                                           // dropped connection — retry next tick
  const snap = JSON.stringify([
    syncSnapshotOf(rows), cfg,
    (notes||[]).map(n=>[n.id, n.body, n.author]),
    (profs||[]).map(p=>[p.id, p.name, p.role, p.color, p.color2]),
    (tl||[]).map(e=>[e.id, e.day_label, e.title, e.notes, e.time_text]),
  ]);
  if(_syncSnapshot === null){ _syncSnapshot = snap; return; }     // (re)baseline, don't re-render
  if(snap === _syncSnapshot){
    // Nothing changed on the wire — but a shown grace window may have quietly run out while
    // this tab was throttled. That still has to hand off at 5:00.
    if(graceOverdue()) refreshCrewGrace();
    return;
  }
  _syncSnapshot = snap;
  CONFIG = cfg;
  PROFILES = profs;
  const y = window.scrollY;
  const id = (document.querySelector('#app .page.active') || {}).id || '';
  try{
    if(id==='page-home') await renderHome();
    else if(id==='page-splits') await renderSplits();
    else if(id==='page-crew') await renderCrewSheet();
    else if(id==='page-checklist') await renderChecklist();
    else if(id==='page-weekend') await renderWeekend();
    else if(id==='page-notes') await renderNotes();
    else if(id==='page-team') await renderTeam();
    const modal = document.getElementById('stop-detail-modal');
    if(modal && !modal.classList.contains('hidden') && modal.dataset.stopId) await openStopDetail(modal.dataset.stopId);
  }catch(e){}
  window.scrollTo(0, y);
}
function startLiveSync(){
  clearInterval(_syncTimer);
  _syncSnapshot = null;
  liveSyncTick();                                     // baseline right now, not 5s from now
  _syncTimer = setInterval(liveSyncTick, SYNC_MS);
}
function stopLiveSync(){ clearInterval(_syncTimer); _syncTimer = null; }
// Any time the app comes back to the foreground (tab shown, window refocused), catch up the
// shared data AND settle any grace window that expired while we were away — timers don't run
// reliably in a backgrounded tab, so this is what actually enforces the 5-minute cap.
function onAppWake(){
  if(document.hidden) return;
  if(graceOverdue()) refreshCrewGrace();
  liveSyncTick();
}
document.addEventListener('visibilitychange', onAppWake);
window.addEventListener('focus', onAppWake);
window.addEventListener('pageshow', onAppWake);

/* ================= INIT ================= */
setInterval(()=>{
  document.querySelectorAll('.rd-resting-timer[data-since-ms]').forEach(el=>{
    const since = parseInt(el.dataset.sinceMs, 10);
    if(!since) return;
    const sec = Math.max(0, Math.round((Date.now()-since)/1000));
    const m = Math.floor(sec/60), s = sec%60;
    el.textContent = `Resting for ${m}:${String(s).padStart(2,'0')}`;
  });
  // Live "Time On Course" clock — ticks up from the moment the start was logged.
  document.querySelectorAll('[data-course-since-ms]').forEach(el=>{
    const since = parseInt(el.dataset.courseSinceMs, 10);
    if(!since) return;
    const t = Math.max(0, Math.round((Date.now()-since)/1000/60));
    el.textContent = `${Math.floor(t/60)}h ${String(t%60).padStart(2,'0')}m`;
  });
  // Post-"Dad Left" grace: tick the visible countdown, and the instant 5:00 is up hand the
  // stop off — a hard backstop in case the one-shot timer got dropped by a throttled tab.
  if(typeof graceOverdue === 'function' && graceOverdue()){ refreshCrewGrace(); }
  else document.querySelectorAll('.grace-note[data-grace-until-ms]').forEach(el=>{
    const left = parseInt(el.dataset.graceUntilMs, 10) - Date.now();
    if(left <= 0){ el.removeAttribute('data-grace-until-ms'); if(typeof refreshCrewGrace === 'function') refreshCrewGrace(); return; }
    const mm = Math.floor(left/60000), ss = Math.floor((left%60000)/1000);
    el.innerHTML = `<i class="ti ti-clock-pause"></i> This stop clears in ${mm}:${String(ss).padStart(2,'0')} — enter anything left, then it moves to your next stop.`;
  });
}, 1000);
(async function init(){
  document.documentElement.setAttribute('data-theme', THEME_MODE);
  // Ric's layer (Ric and Sydney only) loads after this file; wait for it before drawing.
  if(window.HermiscusBeforeStart) await window.HermiscusBeforeStart;
  const requestedProfile = window.HermiscusAuth.profileName();
  if(requestedProfile){
    PROFILES = await dbList('profiles', 'created_at.asc');
    const profile = PROFILES.find(p=>p.name.toLowerCase()===requestedProfile.toLowerCase());
    if(!profile){
      document.getElementById('profile-grid').innerHTML = '<div class="profile-empty">Your crew profile is not ready. Ask a manager for help.</div>';
      return;
    }
    ME = {id:profile.id, name:profile.name, role:profile.role, color:profile.color, color2:profile.color2};
    localStorage.setItem('hermesco_me', JSON.stringify(ME));
    await showApp();
  } else if(window.HermiscusAuth.demo){
    await renderProfileScreen();
  }
})();

